-- testdata-attendance-2months.sql - TEST DATA ONLY (not part of the official seed)
-- Attendance from Sep 1 to Nov 10, 2026 (two full months = 4 pay cutoffs, plus Nov 1-10 up to the demo),
-- so HR can run payroll for any cutoff and the Attendance DTR, logs and summary have real history.
-- REPLACES testdata-attendance.sql (Oct 16-31): you do not need to import that one too.
--
-- Import on the DB host AFTER schema.sql and seed.sql (and testdata-hr.sql, if you want EMP-0008 to EMP-0012):
--   phpMyAdmin -> mindafresh_db -> Import. Safe to import again: it replaces its own date range.
-- It DELETES every attendance log from Sep 1 to Nov 10 for these employees first (old test punches too).
-- Punches made on Nov 11 or later are not touched.
--
-- Shift 08:00-17:00, Monday-Saturday, lunch about 12:00-13:00 (pay always deducts 1 hour), max 8.00 h a day.
-- 61 working days (Nov 1 is a holiday). Employees that do not exist are skipped.
-- Andrea Flores (EMP-0012, resigned) has logs only up to Sep 30, her last day.
-- Oct 16-31 for EMP-0001 to EMP-0007 is the same as in testdata-attendance.sql, except 4 overtime days (v2.5):
--   Jose Oct 20 out 19:00 (120 min), Ramon Oct 24 out 18:45 (105 min), Maria Oct 30 out 17:45 (45 min),
--   Pedro Oct 17 out 17:20 (20 min: under 30, so no overtime). Other days have overtime about 5% of the time.
-- NEEDS migration 006-overtime.sql first (the overtime_minutes column).
-- Totals before leave days are added:
--   EMP-0001 Roberto : 58 present, 3 late, 0 absent, 2 undertime, overtime on 3 days (165 min)
--   EMP-0002 Maria   : 56 present, 5 late, 0 absent, 1 undertime, overtime on 1 days (45 min)
--   EMP-0003 Jose    : 59 present, 1 late, 1 absent, 3 undertime, overtime on 2 days (240 min)
--   EMP-0004 Liza    : 54 present, 7 late, 0 absent, 2 undertime, overtime on 3 days (225 min)
--   EMP-0005 Carla   : 54 present, 5 late, 2 absent, 1 undertime, overtime on 1 days (30 min)
--   EMP-0006 Pedro   : 53 present, 7 late, 0 absent, overtime on 5 days (375 min)
--   EMP-0007 Ramon   : 56 present, 3 late, 2 absent, 1 undertime, overtime on 1 days (105 min)
--   EMP-0008 Grace   : 51 present, 9 late, 0 absent, 1 undertime
--   EMP-0009 Mark    : 57 present, 2 late, 1 absent, 2 undertime, overtime on 1 days (60 min)
--   EMP-0010 Joy     : 56 present, 2 late, 1 absent, 1 undertime, overtime on 2 days (195 min)
--   EMP-0011 Carlo   : 56 present, 3 late, 2 absent, 2 undertime, overtime on 1 days (30 min)
--   EMP-0012 Andrea  : 25 present, 1 late, 0 absent, 1 undertime
-- Approved leaves in this file become 'on_leave' days: Joy Sep 14-15, Mark Sep 22, Grace Oct 5, Pedro Oct 23.
-- Approved leaves already in the database (for example from testdata-hr.sql) also become 'on_leave'.
USE mindafresh_db;
SET time_zone = '+08:00';

-- 1. Remove this file's earlier rows
DELETE a FROM attendance_logs a JOIN employees e ON e.id = a.employee_id
  WHERE a.log_date BETWEEN '2026-09-01' AND '2026-11-10' AND e.employee_code IN ('EMP-0001', 'EMP-0002', 'EMP-0003', 'EMP-0004', 'EMP-0005', 'EMP-0006', 'EMP-0007', 'EMP-0008', 'EMP-0009', 'EMP-0010', 'EMP-0011', 'EMP-0012');
DELETE FROM leave_requests WHERE reason LIKE '%(attendance test data)' OR reason = 'Family trip (test data)';

-- 2. Approved leaves, approved by Liza Mendoza (HR, EMP-0004)
SELECT e.id, l.t, l.s, l.e, l.d, CONCAT(l.r, ' (attendance test data)'), 'approved',
       (SELECT id FROM employees WHERE employee_code = 'EMP-0004')
FROM (
  SELECT 'EMP-0010' AS code, 'vacation' AS t, DATE('2026-09-14') AS s, DATE('2026-09-15') AS e, 2 AS d, 'Sister''s wedding in Batangas' AS r
  UNION ALL
  SELECT 'EMP-0009' AS code, 'sick' AS t, DATE('2026-09-22') AS s, DATE('2026-09-22') AS e, 1 AS d, 'Flu, with medical certificate' AS r
  UNION ALL
  SELECT 'EMP-0008' AS code, 'sick' AS t, DATE('2026-10-05') AS s, DATE('2026-10-05') AS e, 1 AS d, 'Dental procedure' AS r
  UNION ALL
  SELECT 'EMP-0006' AS code, 'vacation' AS t, DATE('2026-10-23') AS s, DATE('2026-10-23') AS e, 1 AS d, 'Family trip' AS r
) l JOIN employees e ON e.employee_code = l.code;
UPDATE leave_requests SET leave_code = CONCAT('LVE-', LPAD(id, 4, '0')) WHERE leave_code IS NULL;

-- 3. The punches, loaded by employee CODE so they land on the right person
DROP TEMPORARY TABLE IF EXISTS tmp_att;
CREATE TEMPORARY TABLE tmp_att (
  code VARCHAR(20), log_date DATE, time_in DATETIME NULL, lunch_out DATETIME NULL, lunch_in DATETIME NULL,
  time_out DATETIME NULL, hours_worked DECIMAL(5,2), late_minutes INT, undertime_minutes INT, overtime_minutes INT, status VARCHAR(20)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT e.id, t.log_date, t.time_in, t.lunch_out, t.lunch_in, t.time_out, t.hours_worked, t.late_minutes, t.undertime_minutes, t.overtime_minutes, t.status
FROM tmp_att t JOIN employees e ON e.employee_code = t.code;
DROP TEMPORARY TABLE tmp_att;

-- 4. Every approved leave in the date range becomes an 'on_leave' day (working days only).
--    First remove the punches this file made on those days, then add the on_leave rows.
DELETE a FROM attendance_logs a
  JOIN leave_requests lr ON lr.employee_id = a.employee_id AND lr.status = 'approved'
                        AND a.log_date BETWEEN lr.start_date AND lr.end_date
  JOIN employees e ON e.id = a.employee_id AND e.employee_code IN ('EMP-0001', 'EMP-0002', 'EMP-0003', 'EMP-0004', 'EMP-0005', 'EMP-0006', 'EMP-0007', 'EMP-0008', 'EMP-0009', 'EMP-0010', 'EMP-0011', 'EMP-0012')
  WHERE a.log_date BETWEEN '2026-09-01' AND '2026-11-10' AND a.status <> 'on_leave';
SELECT lr.employee_id, d.day, 0.00, 0, 0, 'on_leave', CONCAT('Approved ', lr.leave_type, ' leave ', lr.leave_code)
FROM leave_requests lr
JOIN (
  SELECT DATE_ADD('2026-09-01', INTERVAL n DAY) AS day
  FROM (SELECT a.i + b.i * 10 AS n FROM
          (SELECT 0 i UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a,
          (SELECT 0 i UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7) b) nums
  WHERE DATE_ADD('2026-09-01', INTERVAL n DAY) <= '2026-11-10'
) d ON d.day BETWEEN lr.start_date AND lr.end_date
JOIN employees e ON e.id = lr.employee_id AND e.employee_code IN ('EMP-0001', 'EMP-0002', 'EMP-0003', 'EMP-0004', 'EMP-0005', 'EMP-0006', 'EMP-0007', 'EMP-0008', 'EMP-0009', 'EMP-0010', 'EMP-0011', 'EMP-0012')
WHERE lr.status = 'approved'
  AND DAYOFWEEK(d.day) <> 1
  AND d.day NOT IN (SELECT holiday_date FROM holidays)
  AND NOT EXISTS (SELECT 1 FROM attendance_logs x WHERE x.employee_id = lr.employee_id AND x.log_date = d.day);

-- 5. Display codes ATT-0001, ATT-0002, ... (normally made by the model's afterCreate hook)
UPDATE attendance_logs SET log_code = CONCAT('ATT-', LPAD(id, 4, '0')) WHERE log_code IS NULL;

-- 6. Leave balances = 5 minus the approved vacation / sick days of 2026
UPDATE employees e SET
  vacation_leave_balance = GREATEST(0, 5 - (SELECT COALESCE(SUM(days), 0) FROM leave_requests
                           WHERE employee_id = e.id AND status = 'approved' AND leave_type = 'vacation' AND YEAR(start_date) = 2026)),
  sick_leave_balance     = GREATEST(0, 5 - (SELECT COALESCE(SUM(days), 0) FROM leave_requests
                           WHERE employee_id = e.id AND status = 'approved' AND leave_type = 'sick' AND YEAR(start_date) = 2026))
WHERE e.employee_code IN ('EMP-0001', 'EMP-0002', 'EMP-0003', 'EMP-0004', 'EMP-0005', 'EMP-0006', 'EMP-0007', 'EMP-0008', 'EMP-0009', 'EMP-0010', 'EMP-0011', 'EMP-0012');

